<template><div class="shell"><AdminSidebar /><main class="main"><header><div><span>管理控制台 / </span><b>操作审计</b></div><el-button circle plain title="刷新" :loading="loading" @click="load"><el-icon><Refresh /></el-icon></el-button></header><section class="heading"><div><h1>操作审计</h1><p>查看管理员对电影、用户和系统任务的操作记录。</p></div></section><el-card shadow="never" class="table-card"><el-table v-loading="loading" :data="events" stripe><el-table-column prop="createdAt" label="时间" width="180" /><el-table-column prop="eventType" label="事件" width="210" /><el-table-column label="结果" width="100"><template #default="{ row }"><el-tag :type="row.outcome === 'SUCCESS' ? 'success' : 'danger'" size="small">{{ row.outcome === 'SUCCESS' ? '成功' : row.outcome }}</el-tag></template></el-table-column><el-table-column prop="actorUserId" label="操作者 ID" width="110" /><el-table-column prop="subject" label="对象" width="150" /><el-table-column prop="metadata" label="详情" min-width="220" show-overflow-tooltip /><el-table-column prop="ipAddress" label="IP" width="140" /><template #empty><el-empty description="暂无审计记录" /></template></el-table><div class="pager"><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="changeSize" /></div></el-card></main></div></template>
<script setup lang="ts">import { onMounted, ref } from 'vue';import { ElMessage } from 'element-plus';import { Refresh } from '@element-plus/icons-vue';import AdminSidebar from '../components/AdminSidebar.vue';import { getAuditEvents } from '../api/admin';const events=ref<any[]>([]),loading=ref(false),page=ref(1),size=ref(20),total=ref(0);async function load(){loading.value=true;try{const r:any=await getAuditEvents({current:page.value,size:size.value});if(r.code!==200)throw new Error(r.message);events.value=r.data?.records||[];total.value=r.data?.total||0}catch(e:any){ElMessage.error(e.message||'审计记录加载失败')}finally{loading.value=false}}function changeSize(){page.value=1;load()}onMounted(load)</script>
<style scoped>.shell{min-height:100vh;background:#f4f6f8;color:#263442}.main{margin-left:220px;padding:0 32px 40px;max-width:1500px}header{height:61px;border-bottom:1px solid #e5e9ed;display:flex;justify-content:space-between;align-items:center;font-size:12px}header span{color:#89949d}.heading{padding:26px 0 20px}.heading h1{margin:0;font-size:23px}.heading p{color:#89949d;font-size:12px;margin:7px 0 0}.table-card{border:1px solid #e5e9ec}.table-card :deep(.el-card__body){padding:0}.pager{display:flex;justify-content:flex-end;padding:15px}.el-table{font-size:12px}@media(max-width:900px){.main{margin-left:180px;padding:0 16px}}</style>
